// M6A-SPEC §6.1, transcribed by hand from the spec table (independent of the descriptors under test): per op the
// Kernel directory, A/R columns, symmetry class, the component modes and the params in order (`*` = primary,
// `(sel)`/`(ptr)` = bound; kinds per the `name: kind` column). Set-ops have no modes or symmetry class.

export interface SpecParam {
  readonly name: string;
  readonly kind: string;
  readonly primary?: true;
  readonly bound?: 'selection' | 'pointer';
}
export interface SpecOp {
  readonly id: string;
  readonly label: string;
  readonly dir: string;
  readonly A: boolean;
  readonly R: boolean;
  /** 'expand' | 'pointer' | 'none'; undefined for set-ops. */
  readonly sym?: 'expand' | 'pointer' | 'none';
  /** Component modes, or 'object' for object-only rows; undefined for set-ops. */
  readonly modes?: readonly ('vertex' | 'edge' | 'face')[] | 'object';
  readonly setOp?: true;
  readonly params: readonly SpecParam[];
}

const p = (name: string, kind: string, extra: Partial<SpecParam> = {}): SpecParam => ({ name, kind, ...extra });
const sel = { bound: 'selection' } as const;
const ptr = { bound: 'pointer' } as const;
const star = { primary: true } as const;
